<?php
namespace App\Filament\Resources;
use App\Models\RequestDocument; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class RequestDocumentResource extends Resource { protected static ?string $model=RequestDocument::class; protected static ?string $navigationGroup='Requests'; protected static ?string $navigationIcon='heroicon-o-paper-clip'; public static function canViewAny():bool{return auth()->user()?->can('documents.view')??false;} public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('service_request_id')->relationship('request','reference')->required(),Forms\Components\TextInput::make('document_type'),Forms\Components\TextInput::make('original_name')->disabled(),Forms\Components\Select::make('verification_status')->options(['pending'=>'Pending','verified'=>'Verified','rejected'=>'Rejected'])->required(),Forms\Components\Textarea::make('rejection_reason')->visible(fn($get)=>$get('verification_status')==='rejected'),Forms\Components\DatePicker::make('expires_at')]);} public static function table(Table $table):Table{return $table->defaultSort('created_at','desc')->columns([Tables\Columns\TextColumn::make('request.reference')->searchable(),Tables\Columns\TextColumn::make('original_name')->searchable(),Tables\Columns\TextColumn::make('mime_type'),Tables\Columns\BadgeColumn::make('verification_status'),Tables\Columns\TextColumn::make('uploader.name'),Tables\Columns\TextColumn::make('created_at')->dateTime()])->filters([Tables\Filters\SelectFilter::make('verification_status')->options(['pending'=>'Pending','verified'=>'Verified','rejected'=>'Rejected'])])->actions([Tables\Actions\EditAction::make(),Tables\Actions\Action::make('verify')->requiresConfirmation()->action(fn(RequestDocument $r)=>$r->update(['verification_status'=>'verified','verified_by'=>auth()->id(),'verified_at'=>now()]))]);} public static function getPages():array{return ['index'=>Pages\ListRequestDocuments::route('/'),'view'=>Pages\ViewRequestDocument::route('/{record}'),'edit'=>Pages\EditRequestDocument::route('/{record}/edit')];} }
